      return result.changes ? send(200, JSON.stringify(getTask.get(Number(taskUpdateMatch[2]), Number(taskUpdateMatch[1])))) : send(404, JSON.stringify({ error: 'Not found' }));
    } catch {
      return send(400, JSON.stringify({ error: 'Invalid request' }));
    }
  }
